def department_costs(engine, year):
    stmt = (
        select(departments.c.name, func.count(employees.c.id), func.sum(employees.c.salary))
        .select_from(departments.outerjoin(employees, employees.c.department_id == departments.c.id))
        .where(or_(employees.c.left_on.is_(None), func.extract("year", employees.c.left_on) >= year))
        .group_by(departments.c.name)
        .order_by(func.sum(employees.c.salary).desc().nullslast())
    )
    with engine.connect() as conn:
        rows = conn.execute(stmt).fetchall()
    total = sum(float(r[2] or 0) for r in rows)
    return {
        "year": year,
        "total": total,
        "departments": [
            {"name": name, "people": people, "cost": float(cost or 0), "share": round(float(cost or 0) / total, 3) if total else 0.0}
            for name, people, cost in rows
        ],
    }

def get_primary_key_column(self, cursor, table_name):
        """Return the column name of the primary key for the given table."""
        # Don't use PRAGMA because that causes issues with some transactions
        cursor.execute(
            "SELECT sql, type FROM sqlite_master "
            "WHERE tbl_name = %s AND type IN ('table', 'view')",
            [table_name]
        )
        row = cursor.fetchone()
        if row is None:
            raise ValueError("Table %s does not exist" % table_name)
        create_sql, table_type = row
        if table_type == 'view':
            # Views don't have a primary key.
            return None
        fields_sql = create_sql[create_sql.index('(') + 1:create_sql.rindex(')')]
        for field_desc in fields_sql.split(','):
            field_desc = field_desc.strip()
            m = re.match('(?:(?:["`\[])(.*)(?:["`\]])|(\w+)).*PRIMARY KEY.*', field_desc)
            if m:
                return m.group(1) if m.group(1) else m.group(2)
        return None

