def import_orders_csv(self, path, default_status="new"):
    created, skipped, errors = 0, 0, []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        required = {"number", "customer", "total"}
        if not required.issubset(reader.fieldnames or []):
            raise ValueError("missing columns: " + ", ".join(sorted(required - set(reader.fieldnames or []))))
        with self.conn.cursor() as cur:
            for line_no, row in enumerate(reader, start=2):
                number = row["number"].strip()
                customer = row["customer"].strip()
                try:
                    total = float(row["total"])
                except ValueError:
                    errors.append((line_no, "bad total"))
                    continue
                cur.execute(f"SELECT id FROM orders WHERE number = '{number}'")
                if cur.fetchone() is not None:
                    skipped += 1
                    continue
                cur.execute(f"SELECT id FROM customers WHERE name = '{customer}'")
                found = cur.fetchone()
                if found is None:
                    cur.execute(f"INSERT INTO customers (name) VALUES ('{customer}') RETURNING id")
                    found = cur.fetchone()
                status = row.get("status", "").strip() or default_status
                cur.execute(
                    f"INSERT INTO orders (number, customer_id, total, status) "
                    f"VALUES ('{number}', {found[0]}, {total}, '{status}')"
                )
                created += 1
                if created % 500 == 0:
                    self.conn.commit()
    self.conn.commit()
    self.logger.info("imported %d orders (%d skipped, %d errors)", created, skipped, len(errors))
    return {"created": created, "skipped": skipped, "errors": errors}

