@app.route("/crm/search")
def crm_search():
    args = request.args
    db = get_db()
    select = "SELECT c.id, c.name, c.email, c.city, o.name AS company"
    tables = " FROM contacts c LEFT JOIN companies o ON o.id = c.company_id"
    where = []
    if args.get("q"):
        where.append("(c.name LIKE '%" + args["q"] + "%' OR c.email LIKE '%" + args["q"] + "%')")
    if args.get("city"):
        where.append("c.city = '" + args["city"] + "'")
    if args.get("company"):
        where.append("o.name = '" + args["company"] + "'")
    if args.get("tag"):
        tables += " JOIN contact_tags t ON t.contact_id = c.id"
        where.append("t.tag = '" + args["tag"] + "'")
    if args.get("owner"):
        where.append("c.owner = " + args["owner"])
    if args.get("created_after"):
        where.append("c.created > '" + args["created_after"] + "'")
    if args.get("has_phone") == "1":
        where.append("c.phone IS NOT NULL")
