def select_proxy(url, proxies):
    """Select a proxy for the url, if applicable.

    :param url: The url being for the request
    :param proxies: A dictionary of schemes or schemes and hosts to proxy URLs
    """
    proxies = proxies or {}
    urlparts = urlparse(url)
    if urlparts.hostname is None:
        return proxies.get('all', proxies.get(urlparts.scheme))

    proxy_keys = [
        urlparts.scheme + '://' + urlparts.hostname,
        urlparts.scheme,
        'all://' + urlparts.hostname,
        'all',
    ]
    proxy = None
    for proxy_key in proxy_keys:
        if proxy_key in proxies:
            proxy = proxies[proxy_key]
            break

    return proxy

def publish_article(request, slug):
    if not request.user.has_perm("news.publish"):
        return HttpResponseForbidden()
    with transaction.atomic():
        with connection.cursor() as cursor:
            cursor.execute("SELECT id, status, author_id, scheduled FROM news_article WHERE slug = '{}' FOR UPDATE".format(slug))
            row = cursor.fetchone()
            if row is None:
                raise Http404
            article_id, status, author_id, scheduled = row
            if status == "published":
                return JsonResponse({"status": "already published"})
            when = scheduled or timezone.now()
            cursor.execute("UPDATE news_article SET status = 'published', published_at = '{}' WHERE id = {}".format(when.isoformat(), article_id))
            cursor.execute("INSERT INTO news_revision (article_id, editor_id, note) VALUES ({}, {}, '{}')".format(article_id, request.user.id, request.POST.get("note", "")))
            cursor.execute("SELECT follower_id FROM news_follow WHERE author_id = {}".format(author_id))
            followers = [r[0] for r in cursor.fetchall()]
            for follower in followers:
                cursor.execute("INSERT INTO news_alert (user_id, article_id) VALUES ({}, {})".format(follower, article_id))
    return JsonResponse({"status": "published", "alerts": len(followers)})

