@app.route("/api/games/<int:game_id>/leaderboard")
def leaderboard(game_id):
    limit = min(request.args.get("limit", 10, type=int), 100)
    user = session.get("user_id")
    cur = mysql.connection.cursor()
    cur.execute(
        "SELECT u.name, SUM(s.points) AS total FROM scores s JOIN users u ON u.id = s.user_id "
        "WHERE s.game_id = %s GROUP BY u.id, u.name ORDER BY total DESC LIMIT %s",
        (game_id, limit),
    )
    rows = cur.fetchall()
    board = [{"rank": i, "name": name, "points": int(total)} for i, (name, total) in enumerate(rows, start=1)]
    me = None
    if user is not None:
        cur.execute("SELECT COALESCE(SUM(points), 0) FROM scores WHERE game_id = %s AND user_id = %s", (game_id, user))
        mine = int(cur.fetchone()[0])
        cur.execute(
            "SELECT COUNT(*) + 1 FROM (SELECT user_id, SUM(points) AS t FROM scores WHERE game_id = %s GROUP BY user_id) x WHERE x.t > %s",
            (game_id, mine),
        )
        me = {"points": mine, "rank": cur.fetchone()[0]}
    return jsonify(board=board, me=me)

def advanced_search(conn, params):
    sql = ["SELECT p.id, p.name, p.price, c.name AS category FROM products p JOIN categories c ON c.id = p.category_id"]
    where = []
    if params.get("q"):
        where.append("(p.name LIKE '%" + params["q"] + "%' OR p.description LIKE '%" + params["q"] + "%')")
    if params.get("category"):
        where.append("c.slug = '" + params["category"] + "'")
    if params.get("min_price"):
        where.append("p.price >= " + params["min_price"])
    if params.get("max_price"):
        where.append("p.price <= " + params["max_price"])
    if params.get("brand"):
        brands = ", ".join("'" + b + "'" for b in params["brand"].split(","))
        where.append("p.brand IN (" + brands + ")")
    if params.get("in_stock") == "1":
        where.append("p.stock > 0")
    if where:
        sql.append("WHERE " + " AND ".join(where))
    sort = params.get("sort", "name")
    direction = "DESC" if params.get("dir") == "desc" else "ASC"
    sql.append("ORDER BY p." + sort + " " + direction)
    page = int(params.get("page", 1))
    sql.append("LIMIT 24 OFFSET " + str((page - 1) * 24))
    rows = conn.execute(" ".join(sql)).fetchall()
    results = []
    for row in rows:
        results.append(
            {
                "id": row[0],
                "name": row[1],
                "price": row[2],
                "category": row[3],
            }
        )
    return {"page": page, "results": results}

