    if params.get("max_price"):
        where.append("p.price <= ?")
        args.append(float(params["max_price"]))
    if params.get("brand"):
        brand_list = params["brand"].split(",")
        where.append("p.brand IN (" + ",".join("?" for _ in brand_list) + ")")
        args += brand_list
    if params.get("in_stock") == "1":
        where.append("p.stock > 0")
    if where:
        sql.append("WHERE " + " AND ".join(where))
    sort = params.get("sort", "name")
    direction = "DESC" if params.get("dir") == "desc" else "ASC"
    sql.append("ORDER BY p." + (sort if sort in ("name", "price", "id") else "name") + " " + direction)
    page = int(params.get("page", 1))
    sql.append("LIMIT 24 OFFSET " + str((page - 1) * 24))
    rows = conn.execute(" ".join(sql), args).fetchall()
    results = []
    for row in rows:
        results.append(
            {
                "id": row[0],
                "name": row[1],
                "price": row[2],
                "category": row[3],
            }
        )
    return {"page": page, "results": results}

