def split_into_weeks(days, start_weekday=0):
    weeks, week = [], []
    for day in days:
        week.append(day)
        if (day.weekday() - start_weekday) % 7 == 6:
            weeks.append(week)
            week = []
    if week:
        weeks.append(week)
    return weeks

