def prune_tenant(conn, tenant, tables, keep_days=90, dry_run=False):
    prunable = {"events": "created_at", "sessions": "last_seen", "audit": "at", "uploads": "uploaded_at"}
    unknown = [t for t in tables if t not in prunable]
    if unknown:
        raise ValueError("cannot prune: " + ", ".join(unknown))
    keep_days = int(keep_days)
    report = {}
    with conn.cursor() as cur:
        for table in tables:
            column = prunable[table]
            cur.execute(
                f"SELECT COUNT(*) FROM {table} WHERE tenant = %s AND {column} < now() - make_interval(days => %s)",
                (tenant, keep_days),
            )
            count = cur.fetchone()[0]
            report[table] = count
            if count and not dry_run:
                cur.execute(
                    f"DELETE FROM {table} WHERE tenant = %s AND {column} < now() - make_interval(days => %s)",
                    (tenant, keep_days),
                )
        if dry_run:
            conn.rollback()
        else:
            cur.execute("INSERT INTO prune_log (tenant, report) VALUES (%s, %s)", (tenant, json.dumps(report)))
            conn.commit()
    return report

def execute_sql(self, returning_fields=None):
        assert not (
            returning_fields and len(self.query.objs) != 1 and
            not self.connection.features.can_return_rows_from_bulk_insert
        )
        self.returning_fields = returning_fields
        with self.connection.cursor() as cursor:
            for sql, params in self.as_sql():
                cursor.execute(sql, params)
            if not self.returning_fields:
                return []
            if self.connection.features.can_return_rows_from_bulk_insert and len(self.query.objs) > 1:
                return self.connection.ops.fetch_returned_insert_rows(cursor)
            if self.connection.features.can_return_columns_from_insert:
                assert len(self.query.objs) == 1
                return [self.connection.ops.fetch_returned_insert_columns(cursor, self.returning_params)]
            return [(self.connection.ops.last_insert_id(
                cursor, self.query.get_meta().db_table, self.query.get_meta().pk.column
            ),)]

