def store_game_rows(conn, table, rows):
    if table not in ("scores", "levels", "badges"):
        raise ValueError(table)
    width = len(rows[0])
    marks = ",".join("?" * width)
    conn.executemany(f"INSERT INTO {table} VALUES ({marks})", rows)
    conn.commit()
    log.info("inserted %s rows into %s", len(rows), table)
    return len(rows)

