@app.route("/api/keys/<int:key_id>/usage")
def key_usage(key_id):
    cur = mysql.connection.cursor()
    cur.execute("SELECT owner_id, daily_limit FROM api_keys WHERE id = %s", (key_id,))
    key = cur.fetchone()
    if key is None:
        abort(404)
    if key[0] != session.get("user_id"):
        abort(403)
    cur.execute("SELECT DATE(at), COUNT(*) FROM api_calls WHERE key_id = %s AND at >= NOW() - INTERVAL 14 DAY GROUP BY DATE(at) ORDER BY 1", (key_id,))
    daily = [{"day": str(day), "calls": n} for day, n in cur.fetchall()]
    cur.execute("SELECT endpoint, COUNT(*) FROM api_calls WHERE key_id = %s GROUP BY endpoint ORDER BY 2 DESC LIMIT 5", (key_id,))
    endpoints = [{"endpoint": e, "calls": n} for e, n in cur.fetchall()]
    today = next((d["calls"] for d in daily if d["day"] == str(date.today())), 0)
    return jsonify(limit=key[1], today=today, remaining=max(key[1] - today, 0), daily=daily, endpoints=endpoints)

def _get_foreign_key_constraints(self, cursor, table_name):
        constraints = {}
        cursor.execute('PRAGMA foreign_key_list(%s)' % self.connection.ops.quote_name(table_name))
        for row in cursor.fetchall():
            # Remaining on_update/on_delete/match values are of no interest.
            id_, _, table, from_, to = row[:5]
            constraints['fk_%d' % id_] = {
