@app.route("/events/<int:event_id>/register", methods=["POST"])
def register_for_event(event_id):
    user_id = session.get("user_id")
    if user_id is None:
        return redirect("/login")
    guests = request.form.get("guests", 0, type=int)
    promo = (request.form.get("promo") or "").strip()
    if guests < 0 or guests > 4:
        flash("you can bring up to four guests")
        return redirect(f"/events/{event_id}")
    cur = mysql.connection.cursor()
    cur.execute("SELECT title, capacity, starts, price, status FROM events WHERE id = %s FOR UPDATE", (event_id,))
    event = cur.fetchone()
    if event is None:
        abort(404)
    title, capacity, starts, price, status = event
    if status != "open" or starts < datetime.utcnow():
        flash("registration is closed")
        return redirect("/events")
    cur.execute("SELECT id FROM registrations WHERE event_id = %s AND user_id = %s AND status != 'cancelled'", (event_id, user_id))
    if cur.fetchone() is not None:
        flash("you are already registered")
        return redirect(f"/events/{event_id}")
    cur.execute("SELECT COALESCE(SUM(1 + guests), 0) FROM registrations WHERE event_id = %s AND status = 'confirmed'", (event_id,))
    taken = cur.fetchone()[0]
    seats = 1 + guests
    state = "confirmed" if taken + seats <= capacity else "waitlisted"
    discount = 0
    if promo:
        cur.execute("SELECT percent FROM promos WHERE code = %s AND event_id = %s AND active = 1", (promo, event_id))
        found = cur.fetchone()
        if found is not None:
            discount = found[0]
    amount = round(price * seats * (100 - discount) / 100, 2)
    if amount < 0:
        amount = 0
    cur.execute(
        "INSERT INTO registrations (event_id, user_id, guests, status, amount) VALUES (%s, %s, %s, %s, %s)",
        (event_id, user_id, guests, state, amount),
    )
    registration_id = cur.lastrowid
    cur.execute("INSERT INTO registration_log (registration_id, note) VALUES (%s, %s)", (registration_id, f"{state}, {seats} seats"))
    logger.info("registration %s for event %s: %s", registration_id, event_id, state)
    mysql.connection.commit()
    flash(f"you are {state} for {title}")
    return redirect(f"/registrations/{registration_id}")

