def pack_tags(tags, width):
    lines, line = [], ""
    for tag in tags:
        label = "#" + tag
        if line and len(line) + 1 + len(label) > width:
            lines.append(line)
            line = label
        else:
            line = f"{line} {label}".strip()
    if line:
        lines.append(line)
    return lines

