def upsert_readings(engine, device, readings):
    rows = [{"device": device, "at": r["at"], "value": r["value"]} for r in readings if r.get("value") is not None]
    if not rows:
        return {"written": 0, "skipped": len(readings)}
    stmt = pg_insert(device_readings).values(rows)
    stmt = stmt.on_conflict_do_update(
        index_elements=["device", "at"],
        set_={"value": stmt.excluded.value},
    )
    with engine.begin() as conn:
        conn.execute(stmt)
        conn.execute(update(devices).where(devices.c.name == device).values(last_seen=func.now()))
    return {"written": len(rows), "skipped": len(readings) - len(rows)}

def execute_sql(self, return_id=False):
        assert not (
            return_id and len(self.query.objs) != 1 and
            not self.connection.features.can_return_ids_from_bulk_insert
        )
        self.return_id = return_id
        with self.connection.cursor() as cursor:
            for sql, params in self.as_sql():
                cursor.execute(sql, params)
            if not (return_id and cursor):
                return
            if self.connection.features.can_return_ids_from_bulk_insert and len(self.query.objs) > 1:
                return self.connection.ops.fetch_returned_insert_ids(cursor)
            if self.connection.features.can_return_id_from_insert:
                assert len(self.query.objs) == 1
                return self.connection.ops.fetch_returned_insert_id(cursor)
            return self.connection.ops.last_insert_id(cursor,
                    self.query.get_meta().db_table, self.query.get_meta().pk.column)

