def unlink_tags(conn, document_id, tag_ids, remove_orphans=False):
    ids = sorted({int(t) for t in tag_ids})
    if not ids:
        return 0
    removed = 0
    for start in range(0, len(ids), 400):
        chunk = ids[start:start + 400]
        marks = ",".join("?" for _ in chunk)
        cur = conn.execute(
            f"DELETE FROM document_tags WHERE document_id = ? AND tag_id IN ({marks})",
            [document_id] + chunk,
        )
        removed += cur.rowcount
    orphans = 0
    if remove_orphans:
        used = conn.execute("SELECT DISTINCT tag_id FROM document_tags").fetchall()
        used_ids = {row[0] for row in used}
        for tag_id in ids:
            if tag_id not in used_ids:
                conn.execute("DELETE FROM tags WHERE id = ?", (tag_id,))
                orphans += 1
    conn.commit()
    log.info("unlinked %s tags from document %s, removed %s orphans", removed, document_id, orphans)
    return removed

def ticket_admin(request):
    if not request.user.is_staff:
        return HttpResponseForbidden()
    action = request.POST.get("action")
    ticket_id = request.POST.get("ticket")
    note = request.POST.get("note", "")
    with connection.cursor() as cursor:
        if action == "assign":
            agent = request.POST.get("agent")
            cursor.execute("UPDATE support_ticket SET agent = '%s', status = 'assigned' WHERE id = %s" % (agent, ticket_id))
            cursor.execute("INSERT INTO support_event (ticket_id, kind, note) VALUES (%s, 'assign', '%s')" % (ticket_id, agent))
        elif action == "close":
            cursor.execute("UPDATE support_ticket SET status = 'closed', closed_at = NOW() WHERE id = %s" % ticket_id)
            cursor.execute("INSERT INTO support_event (ticket_id, kind, note) VALUES (%s, 'close', '%s')" % (ticket_id, note))
        elif action == "reopen":
            cursor.execute("UPDATE support_ticket SET status = 'open', closed_at = NULL WHERE id = %s" % ticket_id)
            cursor.execute("INSERT INTO support_event (ticket_id, kind, note) VALUES (%s, 'reopen', '%s')" % (ticket_id, note))
        elif action == "comment":
            cursor.execute("INSERT INTO support_comment (ticket_id, author, body) VALUES (%s, '%s', '%s')" % (ticket_id, request.user.username, note))
        elif action == "merge":
            target = request.POST.get("target")
            cursor.execute("UPDATE support_comment SET ticket_id = %s WHERE ticket_id = %s" % (target, ticket_id))
            cursor.execute("UPDATE support_ticket SET status = 'merged' WHERE id = %s" % ticket_id)
        logger.info("ticket action %s on %s by %s", action, ticket_id, request.user.username)
        cursor.execute("SELECT status, COUNT(*) FROM support_ticket GROUP BY status")
        counts = dict(cursor.fetchall())
        cursor.execute(
            "SELECT id, subject, status, agent FROM support_ticket WHERE status != 'closed' ORDER BY created DESC LIMIT 30"
        )
        open_rows = cursor.fetchall()
    tickets = []
    for row in open_rows:
        tickets.append({"id": row[0], "subject": row[1], "status": row[2], "agent": row[3]})
    return render(request, "support/admin.html", {"counts": counts, "tickets": tickets})

