def summarize_requests(lines):
    stats = {"total": 0, "errors": 0, "bytes": 0, "slowest": None}
    by_status = {}
    by_path = {}
    for line in lines:
        parts = line.split()
        if len(parts) < 5:
            continue
        method, path, status, size, millis = parts[0], parts[1], int(parts[2]), int(parts[3]), float(parts[4])
        stats["total"] += 1
        stats["bytes"] += size
        by_status[status] = by_status.get(status, 0) + 1
        by_path[path] = by_path.get(path, 0) + 1
        if status >= 500:
            stats["errors"] += 1
        if stats["slowest"] is None or millis > stats["slowest"][1]:
            stats["slowest"] = (path, millis)
    top = sorted(by_path.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
    stats["error_rate"] = round(stats["errors"] / stats["total"], 4) if stats["total"] else 0.0
    return {"stats": stats, "by_status": by_status, "top_paths": top}

