    user_id = g.user["id"]
    row = db.execute("SELECT 1 FROM favourites WHERE user_id = ? AND item_id = ?", (user_id, item_id)).fetchone()
    if row is None:
        db.execute("INSERT INTO favourites (user_id, item_id) VALUES (?, ?)", (user_id, item_id))
