def top_by_metric(conn, table, metric, limit=10):
    tables = {"players": ("name", ("score", "wins", "games")), "teams": ("name", ("points", "wins"))}
    if table not in tables:
        raise ValueError("unknown table")
    name_col, metrics = tables[table]
    if metric not in metrics:
        raise ValueError("unknown metric")
    limit = max(1, min(int(limit), 100))
    rows = conn.execute(
        f"SELECT {name_col}, {metric} FROM {table} ORDER BY {metric} DESC LIMIT ?",
        (limit,),
    ).fetchall()
    return [{"name": r[0], "value": r[1]} for r in rows]

