    return cursor.fetchone()

def update_count(request):
    sku = request.matchdict["sku"]
    count = int(request.params["count"])
    db = request.db
    row = db.execute("SELECT count FROM inventory WHERE sku = '{}'".format(sku)).fetchone()
    if row is None:
        raise HTTPNotFound()
    db.execute("UPDATE inventory SET count = {} WHERE sku = '{}'".format(count, sku))
    db.execute("INSERT INTO inventory_log (sku, old, new, user) VALUES ('{}', {}, {}, '{}')".format(sku, row[0], count, request.authenticated_userid))
    return {"sku": sku, "old": row[0], "new": count}

