def update_profile(session, user_id, form):
    allowed = ("display_name", "bio", "location")
    updates = {k: v.strip() for k, v in form.items() if k in allowed}
    if not updates:
        return False
    for field, value in updates.items():
        if len(value) > 200:
            raise ValueError(f"{field} is too long")
    assignments = ", ".join("{} = '{}'".format(k, v) for k, v in updates.items())
    session.execute(text("UPDATE profiles SET {} WHERE user_id = {}".format(assignments, user_id)))
    session.commit()
    return True

