def parse_settings(text):
    result = {}
    for number, line in enumerate(text.splitlines(), start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"line {number}: expected key=value")
        result[key.strip()] = value.strip()
    return result

def export_csv_lines(conn, table, columns, since=None, until=None, max_rows=1000):
    registry = {
        "donations": ("donations", ("id", "donor", "amount", "currency", "given_on")),
        "volunteers": ("volunteers", ("id", "name", "team", "hours", "joined_on")),
        "events": ("events", ("id", "title", "venue", "starts_on", "capacity")),
    }
    entry = registry.get(table)
    if entry is None:
        raise ValueError("unknown table")
    table_name, known = entry
    selected = []
    for column in columns:
        if column not in known:
            raise ValueError("unknown column: " + str(column))
        selected.append(column)
    if not selected:
        selected = list(known)
    date_column = known[-1]
    conditions = []
    values = []
    if since:
        conditions.append(date_column + " >= ?")
        values.append(since)
    if until:
        conditions.append(date_column + " <= ?")
        values.append(until)
    where = (" WHERE " + " AND ".join(conditions)) if conditions else ""
    limit = max(1, min(int(max_rows), 5000))
    query = "SELECT " + ", ".join(selected) + " FROM " + table_name + where + " ORDER BY " + known[0] + " LIMIT " + str(limit)
    rows = conn.execute(query, values).fetchall()
    lines = [",".join(selected)]
    totals = {}
    for row in rows:
        lines.append(",".join(str(cell) for cell in row))
        for name, cell in zip(selected, row):
            if isinstance(cell, (int, float)):
                totals[name] = totals.get(name, 0) + cell
    footer = ["rows=" + str(len(rows))]
    for name in selected:
        if name in totals:
            footer.append(name + "_total=" + str(round(totals[name], 2)))
    lines.append(";".join(footer))
    return lines

def safeSQLIdentificatorNaming(name, isTable=False):
    """
    Returns a safe representation of SQL identificator name (internal data format)

    # Reference: http://stackoverflow.com/questions/954884/what-special-characters-are-allowed-in-t-sql-column-retVal

    >>> pushValue(kb.forcedDbms)
    >>> kb.forcedDbms = DBMS.MSSQL
    >>> getText(safeSQLIdentificatorNaming("begin"))
    '[begin]'
    >>> getText(safeSQLIdentificatorNaming("foobar"))
    'foobar'
    >>> kb.forceDbms = popValue()
    """

    retVal = name

    if isinstance(name, six.string_types):
        retVal = getUnicode(name)
        _ = isTable and Backend.getIdentifiedDbms() in (DBMS.MSSQL, DBMS.SYBASE)

        if _:
            retVal = re.sub(r"(?i)\A\[?%s\]?\." % DEFAULT_MSSQL_SCHEMA, "%s." % DEFAULT_MSSQL_SCHEMA, retVal)

        if retVal.upper() in kb.keywords or (retVal or " ")[0].isdigit() or not re.match(r"\A[A-Za-z0-9_@%s\$]+\Z" % ('.' if _ else ""), retVal):  # MsSQL is the only DBMS where we automatically prepend schema to table name (dot is normal)
            retVal = unsafeSQLIdentificatorNaming(retVal)

            if Backend.getIdentifiedDbms() in (DBMS.MYSQL, DBMS.ACCESS, DBMS.SQLITE):  # Note: in SQLite double-quotes are treated as string if column/identifier is non-existent (e.g. SELECT "foobar" FROM users)
                retVal = "`%s`" % retVal
            elif Backend.getIdentifiedDbms() in (DBMS.PGSQL, DBMS.DB2, DBMS.HSQLDB, DBMS.H2, DBMS.INFORMIX):
                retVal = "\"%s\"" % retVal
            elif Backend.getIdentifiedDbms() in (DBMS.ORACLE,):
                retVal = "\"%s\"" % retVal.upper()
            elif Backend.getIdentifiedDbms() in (DBMS.MSSQL, DBMS.SYBASE):
                if isTable:
                    parts = retVal.split('.', 1)
                    for i in xrange(len(parts)):
                        if parts[i] and (re.search(r"\A\d|[^\w]", parts[i], re.U) or parts[i].upper() in kb.keywords):
                            parts[i] = "[%s]" % parts[i]
                    retVal = '.'.join(parts)
                else:
                    if re.search(r"\A\d|[^\w]", retVal, re.U) or retVal.upper() in kb.keywords:
                        retVal = "[%s]" % retVal

        if _ and DEFAULT_MSSQL_SCHEMA not in retVal and '.' not in re.sub(r"\[[^]]+\]", "", retVal):
            retVal = "%s.%s" % (DEFAULT_MSSQL_SCHEMA, retVal)

    return retVal

