    if site_filter:
        clauses.append("site_code = :site")
        params["site"] = site_filter
    if visitor:
        clauses.append("visitor_name LIKE :visitor")
        params["visitor"] = "%" + visitor + "%"
    if since:
        clauses.append("arrived_at >= :since")
        params["since"] = since
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
