def build_seat_map(self, flight_id):
    with self.conn.cursor() as cur:
        cur.execute("SELECT rows, seats_per_row FROM aircraft a JOIN flights f ON f.aircraft_id = a.id WHERE f.id = %s", (flight_id,))
        layout = cur.fetchone()
        if layout is None:
            raise LookupError(flight_id)
        cur.execute("SELECT seat, passenger_id FROM seat_assignments WHERE flight_id = %s", (flight_id,))
        taken = {seat: passenger for seat, passenger in cur.fetchall()}
    rows, per_row = layout
    letters = "ABCDEFGHJK"[:per_row]
    seat_map = []
    for number in range(1, rows + 1):
        row = []
        for letter in letters:
            seat = f"{number}{letter}"
            row.append({"seat": seat, "free": seat not in taken})
        seat_map.append(row)
    free = sum(1 for row in seat_map for seat in row if seat["free"])
    return {"flight": flight_id, "free": free, "taken": rows * per_row - free, "rows": seat_map}

