def activity_by(conn, user, period):
    formats = {"day": "%Y-%m-%d", "week": "%Y-%W", "month": "%Y-%m"}
    fmt = formats.get(period, "%Y-%m-%d")
    rows = conn.execute(
        "SELECT strftime(?, ts), COUNT(*) FROM activity WHERE user = ? GROUP BY 1", (fmt, user)
    ).fetchall()
    return {bucket: n for bucket, n in rows}

