        for adrq, uri in adrqs
    ]

    return QueuedEventCollectionResponse(
        queued_events=[
            QueuedEventResponse.model_validate(queued_event, from_attributes=True)
            for queued_event in queued_events
        ],
        total_entries=total_entries,
    )

