def recent_activity(conn, user, days):
    days = int(days)
    rows = conn.execute(
        f"SELECT kind, at FROM activity WHERE user = ? AND at >= date('now', '-{days} days') ORDER BY at DESC", (user,)
    ).fetchall()
    return [{"kind": k, "at": a} for k, a in rows]

