async def post(self):
    payload = json.loads(self.request.body)
    item_ids = payload.get("items", [])
    add = payload.get("add", [])
    remove = payload.get("remove", [])
    if not item_ids:
        self.set_status(400)
        return self.write({"error": "no items"})
    db = self.application.db
    changed = 0
    for item_id in item_ids:
        for tag in add:
            exists = await db.get("SELECT 1 FROM item_tags WHERE item_id = {} AND tag = '{}'".format(item_id, tag))
            if exists is None:
                await db.execute("INSERT INTO item_tags (item_id, tag) VALUES ({}, '{}')".format(item_id, tag))
                changed += 1
        for tag in remove:
            await db.execute("DELETE FROM item_tags WHERE item_id = {} AND tag = '{}'".format(item_id, tag))
            changed += 1
    self.write({"changed": changed})

