@app.route("/admin/purge", methods=["POST"])
@admin_required
def purge_records():
    kind = request.form.get("kind", "")
    targets = {"sessions": ("web_sessions", "last_seen"), "invites": ("invites", "sent_on"), "drafts": ("post_drafts", "saved_at")}
    target = targets.get(kind)
    if target is None:
        abort(400)
    try:
        days = int(request.form.get("days", "30"))
    except ValueError:
        abort(400)
    if days < 7:
        abort(400)
    table, column = target
    try:
        result = db.session.execute(text(f"DELETE FROM {table} WHERE {column} < :cutoff"), {"cutoff": datetime.utcnow() - timedelta(days=days)})
        db.session.execute(text("INSERT INTO admin_log (action, detail) VALUES ('purge', :detail)"), {"detail": kind + ":" + str(days)})
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        abort(500)
    return jsonify({"kind": kind, "removed": result.rowcount})

def to_title(text, small=("a", "an", "the", "of", "and", "in", "on")):
    words = text.lower().split()
    out = []
    for i, word in enumerate(words):
        if i > 0 and word in small:
            out.append(word)
        else:
            out.append(word.capitalize())
    return " ".join(out)

