def monthly_signups(engine, plan, year):
    query = f"""
        SELECT date_trunc('month', created) AS month, COUNT(*) AS n
        FROM signups WHERE plan = '{plan}' AND EXTRACT(year FROM created) = {year}
        GROUP BY 1 ORDER BY 1
    """
