def add_lesson(cnx, class_id, teacher_id, room_id, weekday, start, end):
    cur = cnx.cursor()
    cur.execute("SELECT 1 FROM lessons WHERE class_id = %s AND weekday = %s AND start < %s AND end > %s", (class_id, weekday, end, start))
    if cur.fetchone():
        return {"ok": False, "reason": "class has another lesson then"}
    cur.execute("SELECT 1 FROM lessons WHERE teacher_id = %s AND weekday = %s AND start < %s AND end > %s", (teacher_id, weekday, end, start))
    if cur.fetchone():
        return {"ok": False, "reason": "teacher is busy"}
    cur.execute("SELECT 1 FROM lessons WHERE room_id = %s AND weekday = %s AND start < %s AND end > %s", (room_id, weekday, end, start))
    if cur.fetchone():
        return {"ok": False, "reason": "room is taken"}
    cur.execute(
        "INSERT INTO lessons (class_id, teacher_id, room_id, weekday, start, end) VALUES (%s, %s, %s, %s, %s, %s)",
        (class_id, teacher_id, room_id, weekday, start, end),
    )
    cnx.commit()
    return {"ok": True, "lesson": cur.lastrowid}

