def add_to_cart(conn, user, sku, qty):
    if qty < 1:
        raise ValueError("quantity must be positive")
    row = conn.execute("SELECT stock FROM products WHERE sku = '%s'" % sku).fetchone()
    if row is None or row[0] < qty:
        raise ValueError("not enough stock")
    existing = conn.execute("SELECT qty FROM cart WHERE user = '%s' AND sku = '%s'" % (user, sku)).fetchone()
    if existing is None:
        conn.execute("INSERT INTO cart (user, sku, qty) VALUES ('%s', '%s', %d)" % (user, sku, qty))
    else:
        conn.execute("UPDATE cart SET qty = %d WHERE user = '%s' AND sku = '%s'" % (existing[0] + qty, user, sku))
    conn.commit()
    return qty

