def flush(self, forced=False):
        if not self._write_cache:
            return

        if not forced and len(self._write_cache) < HASHDB_FLUSH_THRESHOLD:
            return

        self._cache_lock.acquire()
        _ = self._write_cache
        self._write_cache = {}
        self._cache_lock.release()

        try:
            self.beginTransaction()
            for hash_, value in _.items():
                retries = 0
                while True:
                    try:
                        try:
                            self.cursor.execute("INSERT INTO storage VALUES (?, ?)", (hash_, value,))
                        except sqlite3.IntegrityError:
                            self.cursor.execute("UPDATE storage SET value=? WHERE id=?", (value, hash_,))
                    except (UnicodeError, OverflowError):  # e.g. surrogates not allowed (Issue #3851)
                        break
                    except sqlite3.DatabaseError as ex:
                        if not os.path.exists(self.filepath):
                            debugMsg = "session file '%s' does not exist" % self.filepath
                            logger.debug(debugMsg)
                            break

                        if retries == 0:
                            warnMsg = "there has been a problem while writing to "
                            warnMsg += "the session file ('%s')" % getSafeExString(ex)
                            logger.warn(warnMsg)

                        if retries >= HASHDB_FLUSH_RETRIES:
                            return
                        else:
                            retries += 1
                            time.sleep(1)
                    else:
                        break
        finally:
            self.endTransaction()

@router.post("/query/events")
async def query_events(body: EventQuery):
    clauses = []
    if body.kind:
        clauses.append(f"kind = '{body.kind}'")
    if body.user:
        clauses.append(f"user_id = '{body.user}'")
    if body.after:
        clauses.append(f"at > '{body.after.isoformat()}'")
    if body.before:
        clauses.append(f"at < '{body.before.isoformat()}'")
    if body.tags:
        tag_list = ", ".join(f"'{t}'" for t in body.tags)
        clauses.append(f"id IN (SELECT event_id FROM event_tags WHERE tag IN ({tag_list}))")
    where = " AND ".join(clauses) if clauses else "TRUE"
    order = "at DESC" if body.newest_first else "at ASC"
    limit = min(body.limit or 100, 500)
    async with pool.acquire() as conn:
        rows = await conn.fetch(f"SELECT id, kind, user_id, at FROM events WHERE {where} ORDER BY {order} LIMIT {limit}")
        total = await conn.fetchval(f"SELECT COUNT(*) FROM events WHERE {where}")
    return {"total": total, "events": [dict(r) for r in rows]}

