@app.route("/api/jobs")
def search_jobs():
    args = request.args
    clauses = ["j.active = 1"]
    if args.get("q"):
        clauses.append("(j.title LIKE '%" + args["q"] + "%' OR j.description LIKE '%" + args["q"] + "%')")
    if args.get("city"):
        clauses.append("j.city = '" + args["city"] + "'")
    if args.get("remote") == "1":
        clauses.append("j.remote = 1")
    if args.get("min_salary"):
        clauses.append("j.salary >= " + args["min_salary"])
    if args.get("skills"):
        skills = args["skills"].split(",")
        clauses.append("j.id IN (SELECT job_id FROM job_skills WHERE skill IN (" + ",".join("'" + s + "'" for s in skills) + "))")
    order = {"new": "j.posted DESC", "pay": "j.salary DESC"}.get(args.get("sort"), "j.posted DESC")
    page = max(int(args.get("page", 1)), 1)
    sql = "SELECT j.id, j.title, j.city, j.salary FROM jobs j WHERE " + " AND ".join(clauses)
    sql += " ORDER BY " + order + " LIMIT 20 OFFSET " + str((page - 1) * 20)
    rows = db.session.execute(text(sql)).fetchall()
    return jsonify({"page": page, "jobs": [dict(r._mapping) for r in rows]})

