@app.route("/api/tasks/bulk", methods=["POST"])
def bulk_update_tasks():
    data = request.get_json()
    ids = [int(i) for i in data.get("ids", [])]
    status = data.get("status")
    if not ids or status not in ("todo", "doing", "done"):
        return jsonify(error="ids and a valid status are required"), 400
    db = get_db()
    marks = ",".join("?" for _ in ids)
    owned = db.execute(
        "SELECT id FROM tasks WHERE owner = ? AND id IN (" + marks + ")",
        [g.user["id"]] + ids,
    ).fetchall()
    owned_ids = [r["id"] for r in owned]
    if len(owned_ids) != len(ids):
        return jsonify(error="some tasks do not belong to you"), 403
    db.execute(
        "UPDATE tasks SET status = ? WHERE id IN (" + marks + ")",
        [status] + ids,
    )
    for task_id in ids:
        db.execute("INSERT INTO task_log (task_id, actor, status) VALUES (?, ?, ?)", (task_id, g.user["id"], status))
    db.commit()
    return jsonify(updated=len(ids), status=status)

