def transfer_project(project_id, old_owner, new_owner, note=""):
    with transaction.atomic():
        project = Project.objects.select_for_update().get(pk=project_id)
        if project.owner_id != old_owner.id:
            raise PermissionError("not the owner")
        if not User.objects.filter(pk=new_owner.id, is_active=True).exists():
            raise ValueError("new owner is not active")
        project.owner = new_owner
        project.save(update_fields=["owner"])
        moved = Task.objects.filter(project=project, assignee=old_owner).update(assignee=new_owner)
        ProjectEvent.objects.create(project=project, kind="transfer", actor=old_owner, detail=note)
        for member in project.members.exclude(pk__in=[old_owner.id, new_owner.id]):
            Notification.objects.create(user=member, text=f"{project.name} has a new owner")
    return {"project": project.pk, "tasks_moved": moved}

