def get_many(self, keys, version=None):
        if not keys:
            return {}

        key_map = {}
        for key in keys:
            new_key = self.make_key(key, version)
            self.validate_key(new_key)
            key_map[new_key] = key

        db = router.db_for_read(self.cache_model_class)
        connection = connections[db]
        quote_name = connection.ops.quote_name
        table = quote_name(self._table)

        with connection.cursor() as cursor:
            cursor.execute(
                'SELECT %s, %s, %s FROM %s WHERE %s IN (%s)' % (
                    quote_name('cache_key'),
                    quote_name('value'),
                    quote_name('expires'),
                    table,
                    quote_name('cache_key'),
                    ', '.join(['%s'] * len(key_map)),
                ),
                list(key_map),
            )
            rows = cursor.fetchall()

        result = {}
        expired_keys = []
        expression = models.Expression(output_field=models.DateTimeField())
        converters = (connection.ops.get_db_converters(expression) + expression.get_db_converters(connection))
        for key, value, expires in rows:
            for converter in converters:
                expires = converter(expires, expression, connection)
            if expires < timezone.now():
                expired_keys.append(key)
            else:
                value = connection.ops.process_clob(value)
                value = pickle.loads(base64.b64decode(value.encode()))
                result[key_map.get(key)] = value
        self._base_delete_many(expired_keys)
        return result

def lookup_animals(self, **criteria):
    parts = []
    for field in ("species", "enclosure", "keeper", "health"):
        value = criteria.get(field)
        if value:
            parts.append(field + " = '" + value + "'")
    sql = "SELECT tag, species, enclosure, keeper, health FROM animals"
    if parts:
        sql += " WHERE " + " AND ".join(parts)
    sql += " ORDER BY tag"
    rows = self.db.fetch_all(sql)
    self.log.info("animal lookup matched %s rows", len(rows))
    return [dict(zip(("tag", "species", "enclosure", "keeper", "health"), row)) for row in rows]

def budget_report(entries, budgets):
    spent = {}
    for entry in entries:
        spent[entry["category"]] = spent.get(entry["category"], 0) + entry["amount"]
    report = []
    for category, limit in sorted(budgets.items()):
        used = spent.get(category, 0)
        remaining = limit - used
        report.append({
            "category": category,
            "limit": limit,
            "spent": round(used, 2),
            "remaining": round(remaining, 2),
            "status": "over" if remaining < 0 else "near" if remaining < limit * 0.1 else "ok",
        })
    unbudgeted = {c: round(v, 2) for c, v in spent.items() if c not in budgets}
    total_limit = sum(budgets.values())
    total_spent = sum(spent.values())
    return {"rows": report, "unbudgeted": unbudgeted, "total_limit": total_limit, "total_spent": round(total_spent, 2)}

