def import_feed(conn, path):
    with open(path, encoding="utf-8") as fh:
        feed = json.load(fh)
    stats = {"inserted": 0, "updated": 0, "rejected": 0}
    for item in feed.get("products", []):
        sku = str(item.get("sku", "")).strip()
        name = str(item.get("name", "")).strip()
        price = item.get("price")
        if not sku or not name or not isinstance(price, (int, float)) or price < 0:
            stats["rejected"] += 1
            continue
        category = str(item.get("category", "misc")).strip()
        existing = conn.execute("SELECT price FROM products WHERE sku = '%s'" % sku).fetchone()
        if existing is None:
            conn.execute(
                "INSERT INTO products (sku, name, price, category) VALUES ('%s', '%s', %s, '%s')"
                % (sku, name, price, category)
            )
            stats["inserted"] += 1
        else:
            if existing[0] != price:
                conn.execute("INSERT INTO price_history (sku, old, new) VALUES ('%s', %s, %s)" % (sku, existing[0], price))
            conn.execute(
                "UPDATE products SET name = '%s', price = %s, category = '%s' WHERE sku = '%s'"
                % (name, price, category, sku)
            )
            stats["updated"] += 1
    conn.commit()
    return stats

